/**
 * @file gifshot.min.js
 * @description 轻量自包含纯原生 JS GIF 编码库
 * 提供标准 GIF89a 动画编码能力与 gifshot 兼容接口，支持透明通道与脱机离线运行
 */

// LZW 字节流打包器
class BitWriter {
  constructor() {
    this.buffer = [];
    this.currentByte = 0;
    this.currentBit = 0;
  }

  writeBits(value, numBits) {
    for (let i = 0; i < numBits; i++) {
      const bit = (value >> i) & 1;
      this.currentByte |= (bit << this.currentBit);
      this.currentBit++;
      if (this.currentBit === 8) {
        this.buffer.push(this.currentByte);
        this.currentByte = 0;
        this.currentBit = 0;
      }
    }
  }

  flush() {
    if (this.currentBit > 0) {
      this.buffer.push(this.currentByte);
      this.currentByte = 0;
      this.currentBit = 0;
    }
  }

  getBytes() {
    this.flush();
    return new Uint8Array(this.buffer);
  }
}

// LZW 压缩算法
function lzwCompress(minCodeSize, pixelIndices) {
  const clearCode = 1 << minCodeSize; // 256
  const eoiCode = clearCode + 1;      // 257

  let codeSize = minCodeSize + 1;
  let nextCode = clearCode + 2;

  const writer = new BitWriter();
  let dictionary = new Map();

  function resetDict() {
    dictionary.clear();
    codeSize = minCodeSize + 1;
    nextCode = clearCode + 2;
  }

  // 发出 Clear Code
  writer.writeBits(clearCode, codeSize);
  resetDict();

  if (pixelIndices.length === 0) {
    writer.writeBits(eoiCode, codeSize);
    return packageSubBlocks(writer.getBytes());
  }

  let prefix = String(pixelIndices[0]);

  for (let i = 1; i < pixelIndices.length; i++) {
    const k = pixelIndices[i];
    const phrase = prefix + ',' + k;
    if (dictionary.has(phrase)) {
      prefix = phrase;
    } else {
      // 写入 prefix 对应的代码
      if (prefix.indexOf(',') === -1) {
        writer.writeBits(parseInt(prefix, 10), codeSize);
      } else {
        writer.writeBits(dictionary.get(prefix), codeSize);
      }

      // 添加新短语到字典
      if (nextCode < 4096) {
        dictionary.set(phrase, nextCode);
        nextCode++;
        if (nextCode > (1 << codeSize) && codeSize < 12) {
          codeSize++;
        }
      } else {
        // 字典满了，发出 Clear Code 并重置
        writer.writeBits(clearCode, codeSize);
        resetDict();
      }

      prefix = String(k);
    }
  }

  // 输出最后的 prefix
  if (prefix.indexOf(',') === -1) {
    writer.writeBits(parseInt(prefix, 10), codeSize);
  } else {
    writer.writeBits(dictionary.get(prefix), codeSize);
  }

  // 写入 EOI Code
  writer.writeBits(eoiCode, codeSize);

  return packageSubBlocks(writer.getBytes());
}

// 将 LZW 数据打包为 GIF 子块 (每个子块最多 255 字节)
function packageSubBlocks(bytes) {
  const output = [];
  let index = 0;
  while (index < bytes.length) {
    const chunkSize = Math.min(255, bytes.length - index);
    output.push(chunkSize);
    for (let i = 0; i < chunkSize; i++) {
      output.push(bytes[index + i]);
    }
    index += chunkSize;
  }
  output.push(0x00); // 块终止符
  return new Uint8Array(output);
}

// 构建 256 色全局调色板 (自适应中位聚类/采样)
function buildPalette(framesData) {
  const colorMap = new Map();
  let hasAlpha = false;

  // 统计所有非透明颜色频率
  for (const data of framesData) {
    const pixels = data.data;
    for (let i = 0; i < pixels.length; i += 4) {
      const a = pixels[i + 3];
      if (a < 128) {
        hasAlpha = true;
      } else {
        // 量化为 5-5-5 减少数量
        const r = pixels[i] & 0xF8;
        const g = pixels[i + 1] & 0xF8;
        const b = pixels[i + 2] & 0xF8;
        const key = (r << 16) | (g << 8) | b;
        colorMap.set(key, (colorMap.get(key) || 0) + 1);
      }
    }
  }

  const sortedColors = Array.from(colorMap.entries())
    .sort((a, b) => b[1] - a[1])
    .map(entry => entry[0]);

  const palette = [];
  // 索引 0 预留为透明色
  palette.push([0, 0, 0]);

  const maxColors = hasAlpha ? 255 : 256;
  const takeCount = Math.min(sortedColors.length, maxColors - 1);

  for (let i = 0; i < takeCount; i++) {
    const key = sortedColors[i];
    const r = (key >> 16) & 0xFF;
    const g = (key >> 8) & 0xFF;
    const b = key & 0xFF;
    palette.push([r, g, b]);
  }

  // 补齐 256 种颜色
  while (palette.length < 256) {
    palette.push([0, 0, 0]);
  }

  return { palette, hasAlpha, transparentIndex: 0 };
}

// 将 ImageData 像素映射为调色板索引
function mapPixelsToPalette(imageData, palette, hasAlpha, transparentIndex) {
  const pixels = imageData.data;
  const numPixels = imageData.width * imageData.height;
  const indices = new Uint8Array(numPixels);

  // 快速颜色查找缓存
  const cache = new Map();

  for (let i = 0, p = 0; i < pixels.length; i += 4, p++) {
    const a = pixels[i + 3];
    if (hasAlpha && a < 128) {
      indices[p] = transparentIndex;
      continue;
    }

    const r = pixels[i];
    const g = pixels[i + 1];
    const b = pixels[i + 2];
    const key = (r << 16) | (g << 8) | b;

    let bestIndex = cache.get(key);
    if (bestIndex === undefined) {
      let minDist = Infinity;
      bestIndex = 1;
      const start = hasAlpha ? 1 : 0;
      for (let j = start; j < palette.length; j++) {
        const pr = palette[j][0];
        const pg = palette[j][1];
        const pb = palette[j][2];
        const dr = r - pr;
        const dg = g - pg;
        const db = b - pb;
        const dist = dr * dr + dg * dg + db * db;
        if (dist < minDist) {
          minDist = dist;
          bestIndex = j;
          if (dist === 0) break;
        }
      }
      cache.set(key, bestIndex);
    }
    indices[p] = bestIndex;
  }

  return indices;
}

/**
 * GIF 编码器核心类
 */
class GIFEncoder {
  constructor(width, height, options = {}) {
    this.width = Math.round(width);
    this.height = Math.round(height);
    this.loop = options.loop !== undefined ? options.loop : 0; // 0 = 无限循环
    this.frames = [];
  }

  /**
   * 添加一帧
   * @param {ImageData|HTMLCanvasElement} frameData 
   * @param {number} delayMs 帧持续时长(毫秒)
   */
  addFrame(frameData, delayMs = 100) {
    let imgData = frameData;
    if (typeof HTMLCanvasElement !== 'undefined' && frameData instanceof HTMLCanvasElement) {
      const ctx = frameData.getContext('2d');
      imgData = ctx.getImageData(0, 0, frameData.width, frameData.height);
    } else if (frameData && frameData.width && frameData.height && frameData.data) {
      imgData = frameData;
    }
    this.frames.push({
      data: imgData,
      delay: Math.max(20, Math.round(delayMs))
    });
  }

  /**
   * 编码为 Uint8Array
   * @returns {Uint8Array}
   */
  encode() {
    if (this.frames.length === 0) {
      throw new Error('GIFEncoder: 没有可编码的帧');
    }

    const width = this.width;
    const height = this.height;

    // 1. 构建调色板
    const { palette, hasAlpha, transparentIndex } = buildPalette(this.frames.map(f => f.data));

    const parts = [];

    // Header: GIF89a
    const header = new Uint8Array([0x47, 0x49, 0x46, 0x38, 0x39, 0x61]);
    parts.push(header);

    // Logical Screen Descriptor (7 字节)
    const lsd = new Uint8Array(7);
    const lsdView = new DataView(lsd.buffer);
    lsdView.setUint16(0, width, true);
    lsdView.setUint16(2, height, true);
    lsd[4] = 0xF7; // GCTF = 1, Color Res = 7, Sort = 0, GCT Size = 7 (256色)
    lsd[5] = transparentIndex; // 背景颜色索引
    lsd[6] = 0; // 像素比例
    parts.push(lsd);

    // Global Color Table (768 字节)
    const gct = new Uint8Array(768);
    for (let i = 0; i < 256; i++) {
      gct[i * 3] = palette[i][0];
      gct[i * 3 + 1] = palette[i][1];
      gct[i * 3 + 2] = palette[i][2];
    }
    parts.push(gct);

    // Netscape Application Extension (循环信息)
    if (this.loop >= 0) {
      const appExt = new Uint8Array([
        0x21, 0xFF, 0x0B,
        0x4E, 0x45, 0x54, 0x53, 0x43, 0x41, 0x50, 0x45, 0x32, 0x2E, 0x30, // "NETSCAPE2.0"
        0x03, 0x01,
        this.loop & 0xFF, (this.loop >> 8) & 0xFF,
        0x00
      ]);
      parts.push(appExt);
    }

    // 逐帧编码
    for (const frame of this.frames) {
      // 帧延时 (单位: 1/100 秒)
      const delayUnits = Math.round(frame.delay / 10);

      // Graphics Control Extension (8 字节)
      const gce = new Uint8Array(8);
      gce[0] = 0x21; // 扩展引导
      gce[1] = 0xF9; // GCE 标识
      gce[2] = 0x04; // 块大小
      // Disposal Method: 2 (Restore to background)
      gce[3] = hasAlpha ? 0x09 : 0x04;
      gce[4] = delayUnits & 0xFF;
      gce[5] = (delayUnits >> 8) & 0xFF;
      gce[6] = transparentIndex;
      gce[7] = 0x00; // 终止符
      parts.push(gce);

      // Image Descriptor (10 字节)
      const id = new Uint8Array(10);
      const idView = new DataView(id.buffer);
      id[0] = 0x2C; // 图像分隔符
      idView.setUint16(1, 0, true); // left
      idView.setUint16(3, 0, true); // top
      idView.setUint16(5, width, true); // width
      idView.setUint16(7, height, true); // height
      id[9] = 0x00; // 无局部颜色表
      parts.push(id);

      // 像素索引与 LZW 压缩
      const pixelIndices = mapPixelsToPalette(frame.data, palette, hasAlpha, transparentIndex);
      const minCodeSize = 8;
      parts.push(new Uint8Array([minCodeSize]));
      const lzwData = lzwCompress(minCodeSize, pixelIndices);
      parts.push(lzwData);
    }

    // Trailer: 0x3B
    parts.push(new Uint8Array([0x3B]));

    // 合并所有数据
    let totalLen = 0;
    for (const p of parts) totalLen += p.length;
    const result = new Uint8Array(totalLen);
    let offset = 0;
    for (const p of parts) {
      result.set(p, offset);
      offset += p.length;
    }

    return result;
  }

  /**
   * 生成 Blob
   * @returns {Blob}
   */
  toBlob() {
    const bytes = this.encode();
    if (typeof Blob !== 'undefined') {
      return new Blob([bytes], { type: 'image/gif' });
    }
    return bytes;
  }
}

/**
 * gifshot 兼容接口门面
 */
const gifshot = {
  createGIF: function(options, callback) {
    try {
      const images = options.images || [];
      const width = options.gifWidth || 256;
      const height = options.gifHeight || 256;
      const interval = options.interval !== undefined ? options.interval : 0.1; // 秒
      const delayMs = Math.round(interval * 1000);

      const encoder = new GIFEncoder(width, height, { loop: options.numFrames !== undefined ? 0 : 0 });

      for (const img of images) {
        encoder.addFrame(img, delayMs);
      }

      const bytes = encoder.encode();
      let dataUrl = '';

      if (typeof window !== 'undefined' && typeof btoa === 'function') {
        let binary = '';
        const len = bytes.byteLength;
        for (let i = 0; i < len; i++) {
          binary += String.fromCharCode(bytes[i]);
        }
        dataUrl = 'data:image/gif;base64,' + btoa(binary);
      }

      if (typeof callback === 'function') {
        callback({
          error: false,
          image: dataUrl,
          bytes: bytes,
          blob: typeof Blob !== 'undefined' ? new Blob([bytes], { type: 'image/gif' }) : null
        });
      }
    } catch (err) {
      if (typeof callback === 'function') {
        callback({ error: true, errorCode: err.message });
      }
    }
  },
  GIFEncoder
};

if (typeof window !== 'undefined') {
  window.gifshot = gifshot;
  window.GIFEncoder = GIFEncoder;
}
if (typeof globalThis !== 'undefined') {
  globalThis.gifshot = gifshot;
  globalThis.GIFEncoder = GIFEncoder;
}

export { GIFEncoder, gifshot };
export default gifshot;
